INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT159-S3-Q8$batch13$, 159, 3, 8, $batch13$Role$batch13$, $batch13$Sinking large, obsolete pieces of equipment in coral areas is said to provide much-needed habitats for marine life. This, proponents say, shows that the practice is ecologically sound. However, it may be that this practice is ecologically unsound even if it does provide much-needed habitats, for the practice may upset an area’s ecological balance in unknown ways.$batch13$, $batch13$Which one of the following most accurately describes the role played in the argument by the claim that the practice of sinking large, obsolete pieces of equipment in coral areas may upset an area’s ecological balance in unknown ways?$batch13$, $batch13$E$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT159-S3-Q8$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$It is intended to be a summary of the argument.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT159-S3-Q8$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$It is a claim that the argument purports to refute.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT159-S3-Q8$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$It is a claim that the argument contends is insufficient to show what some have taken it to show.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT159-S3-Q8$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$It is the main conclusion of the argument.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT159-S3-Q8$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$It is a premise of the argument.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT159-S3-Q8$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT159-S3-Q8$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Opposing Point$batch13$, $batch13$Proponents say sinking old equipment provides needed habitat for marine life, so the practice is ecologically sound.$batch13$), (1, $batch13$Conclusion$batch13$, $batch13$The practice may be ecologically unsound even if it does provide needed habitat.$batch13$), (2, $batch13$Evidence$batch13$, $batch13$The practice may upset an area's ecological balance in unknown ways.$batch13$), (3, $batch13$Evaluate$batch13$, $batch13$"However" turns against the proponents. The conclusion is the claim right after it. "For" then introduces the reason: the practice may upset the ecological balance. So the named claim is the premise.$batch13$), (4, $batch13$Goal$batch13$, $batch13$The claim is a premise.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT159-S3-Q8$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$It doesn't summarize anything. It's one reason.$batch13$), ($batch13$B$batch13$, $batch13$The argument uses this claim. It refutes the proponents' inference.$batch13$), ($batch13$C$batch13$, $batch13$This describes the habitat claim: the argument says habitat isn't enough to show the practice is sound.$batch13$), ($batch13$D$batch13$, $batch13$The conclusion is that the practice may be unsound even with the habitat. The claim in the stem follows "for", which marks support.$batch13$), ($batch13$E$batch13$, $batch13$It's the reason given for the conclusion.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT159-S3-Q8$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
